(function () {
  'use strict';
  // Retirement savings, four ways. Monthly compounding at i = annual rate / 12, deposits at the
  // end of each month, n = months:
  //   FV  = P(1+i)^n + PMT((1+i)^n - 1)/i            (i = 0: P + PMT n)
  //   PMT = (FV - P(1+i)^n) i / ((1+i)^n - 1)
  //   n   = ln((FV i + PMT) / (P i + PMT)) / ln(1+i)  (i = 0: (FV - P) / PMT), rounded up to a month
  //   rate: bisection on 0-100% (FV rises with the rate).
  // Checked in Node (scratch tests, against an independent Python loop): $50,000 + $1,000/month at
  //   6% for 25 years = $916,242.45 (1.005^300 = 4.46497, annuity factor 692.994); monthly needed
  //   for $1,000,000 = $1,120.86; $1,000/month from $50,000 to $1,000,000 at 6% ->
  //   ln(6,000 / 1,250) / ln(1.005) = 314.5 -> 315 months (26 yrs 3 mos); the rate that turns
  //   $50,000 + $1,000/month into $916,242.45 in 25 years solves back to 6.00%;
  //   0% return: $1,000/month for 25 years + $50,000 = $350,000.
  var MAX_MONTHS = 1200;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function fv(P, pmt, rate, n) {
    var i = rate / 12;
    if (i === 0) return P + pmt * n;
    var g = Math.pow(1 + i, n);
    return P * g + pmt * (g - 1) / i;
  }
  function pmtFor(target, P, rate, n) {
    var i = rate / 12;
    var need = target - (i === 0 ? P : P * Math.pow(1 + i, n));
    if (need <= 0) return 0;
    return i === 0 ? need / n : need * i / (Math.pow(1 + i, n) - 1);
  }
  function monthsFor(target, P, pmt, rate) {
    if (target <= P) return 0;
    var i = rate / 12, n;
    if (i === 0) n = pmt > 0 ? (target - P) / pmt : Infinity;
    else if (P * i + pmt <= 0) n = Infinity;
    else n = Math.log((target * i + pmt) / (P * i + pmt)) / Math.log(1 + i);
    return isFinite(n) ? Math.ceil(n - 1e-9) : Infinity;
  }
  function rateFor(target, P, pmt, n) {
    if (fv(P, pmt, 0, n) >= target) return 0;
    if (fv(P, pmt, 1, n) < target) return Infinity;
    var lo = 0, hi = 1;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (fv(P, pmt, mid, n) < target) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function show(id, on) { var el = document.getElementById(id); if (el) el.hidden = !on; }
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12;
    return y + (y === 1 ? ' year' : ' years') + (m ? ' ' + m + (m === 1 ? ' month' : ' months') : '');
  }

  function update() {
    var mode = document.getElementById('rsMode').value;
    show('rsTargetWrap', mode !== 'fv');
    show('rsMonthlyWrap', mode !== 'pmt');
    show('rsYearsWrap', mode !== 'years');
    show('rsRateWrap', mode !== 'rate');
    var P = num('rsCurrent'), target = num('rsTarget'), pmt = num('rsMonthly'), years = num('rsYears'),
        rate = num('rsRate'), infl = num('rsInflation');
    if (isNaN(infl)) infl = 0;
    var error = document.getElementById('rsError'), problems = [];
    if (!(P >= 0)) problems.push('savings of 0 or more');
    if (mode !== 'fv' && !(target >= 0)) problems.push('a goal of 0 or more');
    if (mode !== 'pmt' && !(pmt >= 0)) problems.push('a monthly saving of 0 or more');
    if (mode !== 'years' && !(years >= 1 && years <= 80)) problems.push('1 to 80 years');
    if (mode !== 'rate' && !(rate >= 0 && rate <= 30)) problems.push('a return from 0 to 30%');
    if (infl < 0 || infl > 20) problems.push('inflation from 0 to 20%');
    error.hidden = problems.length === 0;
    if (problems.length) { error.textContent = 'Enter ' + problems.join(', ') + '.'; return; }

    var r = rate / 100, n = Math.round(years * 12), note = '', ok = true;
    if (mode === 'pmt') {
      pmt = pmtFor(target, P, r, n);
      if (pmt === 0) note = 'Your current savings alone grow past your goal in this time, so you do not need to add anything.';
    } else if (mode === 'years') {
      n = monthsFor(target, P, pmt, r);
      if (n === 0) note = 'You have already reached your goal.';
      else if (!isFinite(n) || n > MAX_MONTHS) { ok = false; note = 'At this saving and return you would not reach your goal within 100 years.'; }
    } else if (mode === 'rate') {
      r = rateFor(target, P, pmt, n);
      if (r === 0) note = 'Your saving alone reaches the goal without any investment return.';
      else if (!isFinite(r)) { ok = false; note = 'You would need more than a 100% yearly return; save more or allow more time.'; }
    }
    var noteEl = document.getElementById('rsNote');
    noteEl.textContent = note; noteEl.hidden = note === '';
    var mainLabel = { pmt: 'Save each month', fv: 'Balance at retirement', years: 'Time to reach your goal', rate: 'Annual return needed' }[mode];
    set('rsMainLabel', mainLabel);
    if (!ok) {
      ['rsMain', 'rsFinal', 'rsReal', 'rsPut', 'rsGrowth'].forEach(function (id) { set(id, '–'); });
      set('rsPmt', money.format(pmt)); set('rsStart', money.format(P));
      set('rsTime', mode === 'years' ? 'Over 100 years' : duration(n));
      set('rsRet', mode === 'rate' ? 'Over 100%' : (r * 100).toFixed(2) + '%');
      document.getElementById('rsSchedule').innerHTML = '';
      return;
    }
    var final = fv(P, pmt, r, n), put = P + pmt * n;
    var real = final / Math.pow(1 + infl / 100, n / 12);
    var main = { pmt: money.format(pmt), fv: whole.format(final), years: duration(n), rate: (r * 100).toFixed(2) + '%' }[mode];
    set('rsMain', main);
    set('rsFinal', whole.format(final));
    set('rsReal', whole.format(real));
    set('rsStart', money.format(P));
    set('rsPmt', money.format(pmt));
    set('rsTime', duration(n));
    set('rsRet', (r * 100).toFixed(2) + '%');
    set('rsPut', whole.format(put));
    set('rsGrowth', whole.format(final - put));

    var rows = [], i = r / 12, bal = P;
    for (var y = 1; (y - 1) * 12 < n; y++) {
      var start = bal, months = Math.min(12, n - (y - 1) * 12);
      for (var m = 0; m < months; m++) bal = bal * (1 + i) + pmt;
      var added = pmt * months;
      rows.push('<tr><td>' + y + '</td><td>' + whole.format(added) + '</td><td>' + whole.format(bal - start - added) +
                '</td><td>' + whole.format(bal) + '</td></tr>');
    }
    document.getElementById('rsSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
